    kind: str
    value: object = None
    args: tuple = ()
    text: str = ""


@dataclass(frozen=True)
class SelectItem:
    expr: Expr
    alias: str = None


@dataclass(frozen=True)
class OrderItem:
    expr: Expr
    descending: bool = False


@dataclass(frozen=True)
class Query:
    distinct: bool
    columns: tuple
    table: str
    where: Expr = None
    group_by: tuple = ()
    having: Expr = None
    order_by: tuple = ()
    limit: int = None
    offset: int = 0


_KEYWORDS = set('SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER ASC DESC LIMIT OFFSET AS OR AND NOT IS NULL IN BETWEEN LIKE TRUE FALSE'.split())


