class Token:
    kind: str
    value: object
    start: int
    end: int


def _lex(sql):
    out, i, n = [], 0, len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
            continue
        start = i
        if c == "'":
            i += 1
            val = []
            while i < n:
                if sql[i] == "'":
                    if i + 1 < n and sql[i + 1] == "'":
                        val.append("'"); i += 2
                    else:
                        i += 1; break
                else:
                    val.append(sql[i]); i += 1
            else:
                raise ParseError("unterminated string literal")
            out.append(Token('STRING', ''.join(val), start, i)); continue
        if c == '"':
            i += 1
            val = []
            while i < n:
                if sql[i] == '"':
                    if i + 1 < n and sql[i + 1] == '"':
                        val.append('"'); i += 2
                    else:
                        i += 1; break
                else:
                    val.append(sql[i]); i += 1
            else:
                raise ParseError("unterminated quoted name")
            out.append(Token('IDENT', ''.join(val), start, i)); continue
        if c.isalpha() or c == '_':
            i += 1
            while i < n and (sql[i].isalnum() or sql[i] == '_'): i += 1
            value = sql[start:i]; upper = value.upper()
            out.append(Token(upper if upper in _KEYWORDS else 'IDENT', value, start, i)); continue
        if c.isdigit() or (c == '.' and i + 1 < n and sql[i + 1].isdigit()):
            i += 1
            while i < n and sql[i].isdigit(): i += 1
            if i < n and sql[i] == '.':
                i += 1
                while i < n and sql[i].isdigit(): i += 1
            raw = sql[start:i]
            out.append(Token('NUMBER', float(raw) if '.' in raw else int(raw), start, i)); continue
