        if two in ('<=', '>=', '!=', '<>', '||'):
            out.append(Token(two, two, i, i + 2)); i += 2; continue
        if c in '=<>+-*/(),;':
            out.append(Token(c, c, i, i + 1)); i += 1; continue
        raise ParseError("unexpected character %r" % c)
    out.append(Token('EOF', None, n, n))
    return out


