    @property
    def t(self): return self.ts[self.i]
    def take(self, kind=None):
        t = self.t
        if kind is not None and t.kind != kind:
            raise ParseError("expected %s, got %s" % (kind, t.value if t.kind != 'EOF' else 'end of query'))
