AGGS = {"count", "sum", "avg", "min", "max"}


def convert(value):
    if value == "":
        return None
    if re.fullmatch(r"-?[0-9]+", value):
        return int(value)
    if re.fullmatch(r"-?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+)", value):
        return float(value)
    return value


def numeric(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def compare(a, b, op):
    if a is None or b is None:
        return None
