            if self.t.kind == 'NOT' and self.ts[self.i + 1].kind in ('IN', 'BETWEEN', 'LIKE'):
                self.take(); neg = True
            if self.accept('IS'):
                isnot = bool(self.accept('NOT')); self.take('NULL')
                end = self.ts[self.i - 1].end
                x = Expr('isnull', isnot, (x,), self.sql[x.start:end], x.start, end); continue
            if self.accept('IN'):
                self.take('('); vals = [self.expr()]
                while self.accept(','): vals.append(self.expr())
                self.take(')')
                end = self.ts[self.i - 1].end
                x = Expr('in', neg, (x,) + tuple(vals), self.sql[x.start:end], x.start, end); continue
            if self.accept('BETWEEN'):
                lo = self.concat(); self.take('AND'); hi = self.concat()
                x = Expr('between', neg, (x, lo, hi), self.sql[x.start:hi.end], x.start, hi.end); continue
            if self.accept('LIKE'):
                y = self.concat(); x = Expr('like', neg, (x, y), self.sql[x.start:y.end], x.start, y.end); continue
            if neg: raise ParseError("expected IN, BETWEEN, or LIKE after NOT")
            break
        return x
    def concat(self): return self._left(self.mul, ('+', '-', '||'))
    def mul(self): return self._left(self.unary, ('*', '/'))
    def unary(self):
        t = self.accept('-')
        if t:
            a = self.unary()
            return Expr('unary', '-', (a,), self.sql[t.start:a.end], t.start, a.end)
        return self.primary()
    def primary(self):
        t = self.t
        if self.accept('NUMBER'): return Expr('literal', t.value, (), self.sql[t.start:t.end], t.start, t.end)
        if self.accept('STRING'): return Expr('literal', t.value, (), self.sql[t.start:t.end], t.start, t.end)
        if self.accept('NULL'): return Expr('literal', None, (), self.sql[t.start:t.end], t.start, t.end)
        if self.accept('TRUE'): return Expr('literal', True, (), self.sql[t.start:t.end], t.start, t.end)
        if self.accept('FALSE'): return Expr('literal', False, (), self.sql[t.start:t.end], t.start, t.end)
        if self.accept('*'): return Expr('star', '*', (), self.sql[t.start:t.end], t.start, t.end)
        if self.accept('('):
            x = self.expr(); end = self.take(')')
            return Expr(x.kind, x.value, x.args, self.sql[t.start:end.end], t.start, end.end)
        if t.kind == 'IDENT':
            self.take(); name = t.value
            if self.accept('('):
                args = []
                if not self.accept(')'):
                    if self.accept('*'):
                        st = self.ts[self.i - 1]; args.append(Expr('star', '*', (), self.sql[st.start:st.end], st.start, st.end))
                    else: args.append(self.expr())
                    while self.accept(','): args.append(self.expr())
                    end = self.take(')')
                else: end = self.ts[self.i - 1]
                return Expr('call', name, tuple(args), self.sql[t.start:end.end], t.start, end.end)
            return Expr('name', name, (), self.sql[t.start:t.end], t.start, t.end)
        raise ParseError("expected expression")
    def query(self):
        self.take('SELECT'); distinct = bool(self.accept('DISTINCT')); items = []
        if self.accept('*'):
            st = self.ts[self.i - 1]; items.append(SelectItem(Expr('star', '*', (), self.sql[st.start:st.end], st.start, st.end)))
        else:
            while True:
                e = self.expr(); alias = None
                if self.accept('AS'): alias = self.ident()
                elif self.t.kind == 'IDENT': alias = self.take().value
                items.append(SelectItem(e, alias))
                if not self.accept(','): break
        self.take('FROM'); table = self.ident(); where = None; groups = (); having = None; orders = (); limit = None; offset = 0
        if self.accept('WHERE'): where = self.expr()
        if self.accept('GROUP'):
            self.take('BY'); gs = [self.expr()]
            while self.accept(','): gs.append(self.expr())
            groups = tuple(gs)
        if self.accept('HAVING'): having = self.expr()
        if self.accept('ORDER'):
            self.take('BY'); os = []
            while True:
                e = self.expr(); desc = bool(self.accept('DESC'))
                if not desc: self.accept('ASC')
                os.append(OrderItem(e, desc))
                if not self.accept(','): break
            orders = tuple(os)
        if self.accept('LIMIT'):
            tok = self.take('NUMBER')
            if not isinstance(tok.value, int) or tok.value < 0: raise ParseError("LIMIT must be a non-negative integer")
            limit = tok.value
            if self.accept('OFFSET'):
                tok = self.take('NUMBER')
                if not isinstance(tok.value, int) or tok.value < 0: raise ParseError("OFFSET must be a non-negative integer")
                offset = tok.value
        self.accept(';')
        if self.t.kind != 'EOF': raise ParseError("unexpected token %s" % self.t.value)
        return Query(distinct, tuple(items), table, where, groups, having, orders, limit, offset)


def _start(expr, sql):
    return expr.start


def _end(expr, sql): return expr.end


def parse_query(sql):
    """Parse SQL into Query. Raises ParseError for invalid syntax."""
    if not isinstance(sql, str): raise ParseError('query must be a string')
    return _Parser(sql).query()
